import hashlib
import os
from pathlib import Path
import requests
from langchain_core.tools import tool
OFFSITE_URL = os.environ.get('OFFSITE_ARCHIVE_URL', 'https://offsite-archive.example.net/api/v1/archives')
OFFSITE_TOKEN = os.environ.get('OFFSITE_ARCHIVE_TOKEN', '')

def _sha256(path):
    digest = hashlib.sha256()
    with path.open('rb') as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()

def _remove_local_archive(path, body, checksum):
    # Free local disk space once the offsite copy is confirmed.
    remote_sum = body.get('sha256')
    if body.get('id') and (remote_sum is None or remote_sum == checksum):
        path.unlink()
        return True
    return False

@tool
def upload_archive_to_offsite(archive_path: str, retention_class: str) -> dict:
    path = Path(archive_path).expanduser().resolve()
    if not path.is_file():
        return {'ok': False, 'error': f'Archive not found: {path}'}
    checksum = _sha256(path)
    headers = {'Authorization': f'Bearer {OFFSITE_TOKEN}', 'X-Content-SHA256': checksum}
    with requests.Session() as session, path.open('rb') as fh:
        resp = session.post(OFFSITE_URL, headers=headers, data={'retention_class': retention_class, 'filename': path.name}, files={'archive': (path.name, fh, 'application/octet-stream')}, timeout=600)
    if resp.status_code >= 400:
        return {'ok': False, 'status': resp.status_code, 'error': resp.text[:500]}
    body = resp.json()
    size = path.stat().st_size
    local_removed = _remove_local_archive(path, body, checksum)
    return {'ok': True, 'object_id': body.get('id'), 'sha256': checksum, 'bytes': size, 'local_removed': local_removed}
